const SHORT = { 25: "stl", 29: "ogtr", 30: "dgtr", 73: "fdls", 43: "fl43", 75: "pf" };

const slugFor = (program, key, id, noteOff) =>
  `${SHORT[program] ?? `f${program}`}-${key}-${id}` + (noteOff === undefined ? "" : `-rel${Math.round(noteOff * 1000)}`);

const PRESET_NAME = { 25: "Acoustic Guitar (steel)", 29: "Overdriven Guitar",
  30: "Distortion Guitar", 43: "Flute", 115: "гибрид флейты",
  48: "String Ensemble 1", 49: "String Ensemble 2",
  73: "Flute", 74: "Recorder", 75: "Panflute", 76: "Bottle Blow",
  77: "Shakuhachi", 78: "Whistle", 79: "Ocarina",
  50: "Synth Strings 1", 51: "Synth Strings 2", 52: "Choir Aahs", 53: "Voice Oohs", 54: "Synth Voice",
  91: "Pad 4 (choir)", 94: "Pad 7 (halo)" };

function inputMtime(build) {
  const p = build.bank ? DEFAULT_SF2 : build.wasmJs;
  try { return fs.statSync(p).mtimeMs; } catch { return null; }
}

const KEY_NAMES = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];
const keyLabel = (key) => KEY_NAMES[key % 12] + String(Math.floor(key / 12) - 1);

const MSK_OFFSET_MS = 3*3600*1000;
function mskOf(ms) {
  const iso = new Date(ms + MSK_OFFSET_MS).toISOString();
  return { date: iso.slice(0, 10), time: iso.slice(11, 16) };
}

const contentHash = (name) => { const m = /\.([0-9a-f]{8})\.flac$/.exec(name); return m ? m[1] : name; };

function buildInstruments(groups) {
  const tabs = new Map();
  for (const g of groups) {
    let tab = tabs.get(g.program);
    if (!tab) {
      const name = PRESET_NAME[g.program];
      tab = { program: g.program, title: name ? `${g.program} · ${name}` : `${g.program}`, keys: new Map(), newest: 0 };
      tabs.set(g.program, tab);
    }

    const kid = `${g.key}` + (g.noteOff === undefined ? "" : `-rel${Math.round(g.noteOff*1000)}`);
    let rec = tab.keys.get(kid);
    if (!rec) {
      rec = { key: g.key, noteOff: g.noteOff,
        title: keyLabel(g.key) + (g.noteOff === undefined ? "" : ` (релиз с ${g.noteOff} с)`),
        items: [] };
      tab.keys.set(kid, rec);
    }
    for (const it of g.items) rec.items.push(it);
  }

  const out = [];
  for (const tab of tabs.values()) {
    const keys = [];
    for (const rec of tab.keys.values()) {
      const ours = rec.items.filter((it) => !it.bank);
      const ref = rec.items.filter((it) => it.bank);
      ours.sort((a, b) => (b.mtime || 0) - (a.mtime || 0));

      const seen = new Set();
      const sections = [];
      for (const it of ours) {
        const key = contentHash(it.src);
        if (seen.has(key)) continue;
        seen.add(key);
        const { date, time } = mskOf(it.mtime || Date.now());
        let sec = sections.find((s) => s.date === date);
        if (!sec) { sec = { date, items: [] }; sections.push(sec); }
        sec.items.push({ time, label: it.label, src: it.src, bytes: it.bytes, build: it.build, desc: it.desc });
        if ((it.mtime || 0) > tab.newest) tab.newest = it.mtime || 0;
      }
      const seenRef = new Set();
      const refUniq = ref.filter((it) => (seenRef.has(contentHash(it.src)) ? false : (seenRef.add(contentHash(it.src)), true)));
      if (refUniq.length) {
        sections.push({ date: "эталон", ref: true,
          items: refUniq.map((it) => ({ time: "", label: it.label, src: it.src, bytes: it.bytes, build: it.build, desc: it.desc })) });
      }
      if (sections.length) keys.push({ key: rec.key, noteOff: rec.noteOff, title: rec.title, sections });
    }
    if (keys.length) out.push({ program: tab.program, title: tab.title, newest: tab.newest, keys });
  }

  out.sort((a, b) => b.newest - a.newest);
  return out;
}

async function main() {
  await initFlac();
  fs.mkdirSync(OUT_DIR, { recursive: true });
  const builds = new Map(BUILDS.map((b) => [b.id, b]));
  const wanted = new Set();
  const groups = [];
  let totalBytes = 0, rendered = 0, reused = 0, missing = 0;

  for (const g of GROUPS) {
    const items = [];
    for (const v of g.variants) {
      const id = typeof v === "string" ? v : v.id;
      const program = typeof v === "string" || v.program === undefined ? g.program : v.program;
      const build = builds.get(id);

      const slug = slugFor(program, g.key, id, g.noteOff) + (build.bank ? `-p${bankProgramFor(program)}` : "");
      const mtime = inputMtime(build);
      const existing = fs.readdirSync(OUT_DIR).filter((f) => f.startsWith(slug + ".") && f.endsWith(".flac"));
      let file = null;
      if (!FORCE && mtime !== null && existing.length === 1) {
        const st = fs.statSync(OUT_DIR + "/" + existing[0]);
        if (st.mtimeMs >= mtime) file = existing[0];
      }
      if (!file) {
        let x = null;
        try {
          x = build.bank
            ? renderBank({ program, key: g.key, noteOff: g.noteOff })
            : await renderOurs({ program, key: g.key, wasmJs: build.wasmJs, noteOff: g.noteOff });
        } catch (err) { x = null; }
        if (!x || !x.length) {
          console.log(`  ${slug}: пропуск (${build.bank ? "банк не отрендерился" : `нет сборки ${build.wasmJs}`})`);
          missing++;
          continue;
        }

        const buf = flacEncode(
          [normalizeSustainRms(x, { sampleRate: SR }).slice(0, Math.round(LENGTH_SEC * SR))], SR).buffer;
        const hash = crypto.createHash("sha256").update(buf).digest("hex").slice(0, 8);
        file = `${slug}.${hash}.flac`;
        fs.writeFileSync(OUT_DIR + "/" + file, buf);
        for (const stale of existing) if (stale !== file) fs.unlinkSync(OUT_DIR + "/" + stale);
        rendered++;
      } else {
        reused++;
      }
      const bytes = fs.statSync(OUT_DIR + "/" + file).size;
      wanted.add(file);
      totalBytes += bytes;

      const bp = bankProgramFor(program);

      const label = build.bank
        ? `${build.label} · пресет ${bp}${PRESET_NAME[bp] ? ` «${PRESET_NAME[bp]}»` : ""}`
        : `${typeof v === "object" && v.label ? v.label
            : build.labels && build.labels[program] ? build.labels[program] : build.label}`;
      const scoped = build.scopes && build.scopes[program];
      items.push({ label, desc: scoped ? scoped + " " + (build.desc || "") : build.desc,
        src: `ab/${file}`, bytes, build: id, bank: !!build.bank, mtime });
    }
    if (items.length) groups.push({ title: g.title, program: g.program, key: g.key, noteOff: g.noteOff, items });
  }

  const instruments = buildInstruments(groups);
  const shown = new Set();
  for (const inst of instruments)
    for (const k of inst.keys)
      for (const sec of k.sections)
        for (const it of sec.items) shown.add(it.src.replace(/^ab\//, ""));

  const shownHashes = new Set();
  for (const f of shown) shownHashes.add(contentHash(f));
  let dropped = 0, droppedBytes = 0;
  for (const f of fs.readdirSync(OUT_DIR)) {
    if (!f.endsWith(".flac") || shown.has(f) || shownHashes.has(contentHash(f))) continue;
    droppedBytes += fs.statSync(OUT_DIR + "/" + f).size;
    fs.unlinkSync(OUT_DIR + "/" + f);
    dropped++;
  }
  if (dropped) console.log(`  удалено лишних ${dropped} файлов (${(droppedBytes/1048576).toFixed(1)} МБ) — их нет в панели`);

  const manifest = {
    generated: new Date().toISOString(),
    note: `A/B-рендеры по ИНСТРУМЕНТАМ: вкладка на программу, внутри — ноты, `
      + `внутри ноты — ДАТЫ по МСК (YYYY-MM-DD), свежие сверху; у каждой версии `
      + `видно время сборки по МСК. Версии, в которых звук этого инструмента не `
      + `менялся (файл тот же самый — имя содержит хеш содержимого), убраны, `
      + `поэтому в списке только те апдейты, где инструмент правился. Громкость `
      + `выровнена по RMS сустейна (иначе банк звучит на 6-10 дБ тише `
      + `синтезатора), поэтому сравнивайте тембр и атаку, а не громкость. `
      + `Длина ${LENGTH_SEC} с. `
      + `Подпись версии и первая фраза подсказки говорят только про открытый `
      + `инструмент (подставляются по вкладке), остальная история правок — про `
      + `весь синтезатор.`,
    instruments,
  };
  fs.writeFileSync(OUT_DIR + "/" + "manifest.json", JSON.stringify(manifest, null, 2) + "\n");
  console.log(`ab: вкладок ${instruments.length}, файлов в панели ${shown.size} `
    + `(${rendered} отрендерено, ${reused} взято готовыми, ${missing} пропущено), `
    + `${(totalBytes / 1024 / 1024).toFixed(2)} МБ в ${OUT_DIR}`);
}


